import numpy as np

rng = np.random.default_rng(seed=20)

def simulate_sampling_distribution(n, n_trials=5000):
    samples = rng.exponential(scale=1.0, size=(n_trials, n))
    return samples.mean(axis=1)

for n in [5, 20, 100, 500]:
    means = simulate_sampling_distribution(n)
    theoretical_se = 1.0 / n   # sigma / sqrt(n), sigma = 1 for Exponential(rate=1)
    print(f'n={n:>4}: empirical std = {means.std():.4f}, theoretical SE = {theoretical_se:.4f}')

